/** Unit-only consumer input shape, not a GUI, IPC, Job or database integration.
 * Gold IDs/N3 were generated by the actual isolated Python Store, not a TS hash
 * reimplementation. Cross-language validation invokes Store._fact without a Store
 * instance. No database is opened and no tuple is interpolated into Python code.
 */
import { spawnSync } from 'node:child_process'
import { resolve } from 'node:path'
import { afterEach, describe, expect, it, vi } from 'vitest'
import golden from '../fixtures/t02-manual-fact-id.json'
import type { DomainRead } from '../../apps/desktop/src/renderer/src/ontology/mainline-api'
import { newManualFactPlan } from '../../apps/desktop/src/renderer/src/ontology/mainline-facts'

type Fact = { id: string; subject: string; predicate: string; object: string }
type Triple = Omit<Fact, 'id'>
const firstId = '3978ae6f12eecb202a58646fb7934b743773f9f332b71028d5a3d46ed38ead34'

function source(): DomainRead {
  return {
    readVersion: 1,
    projectId: '00000000-0000-4000-8000-000000000001',
    inputSnapshotId: 'a'.repeat(64),
    workspace: { draft: { state: 'missing', editor: 'ontology-transaction' } },
    domain: {
      projectRevision: 3,
      dependencyVector: { 'facts:asserted': 2, 'ontology:unrelated': 1 },
      state: {
        definitions: [{ layer: 'ontology', id: 'unrelated', payload: '{"triples":[]}' }],
        facts: [
          {
            id: 'b'.repeat(64),
            subject: 'urn:other',
            predicate: 'urn:other:p',
            object: null,
            owner: 'mapping-unrelated',
            source_row: 'row-unrelated',
            managed_value: '"historical"',
          },
        ],
        mappingState: { 'mapping-unrelated': { generatedVersion: 1, stale: [] } },
      },
    },
  }
}
function triple(record: Fact): Triple {
  return { subject: record.subject, predicate: record.predicate, object: record.object }
}
function vector(name: string) {
  const found = golden.cases.find((item) => item.name === name)
  if (!found) throw new Error(`Missing fixed Python golden vector: ${name}`)
  return found
}

const pythonCheck = `import sys,json
sys.path.insert(0,sys.argv[1])
from ontolearn_engine.storage import Store,canonical,digest
records=json.load(sys.stdin)
canonicals=[]
for record in records:
    Store._fact(record)
    values=[record["subject"],record["predicate"],record["object"]]
    assert record["id"]==digest(values)
    canonicals.append(canonical(values))
print(json.dumps({"accepted":len(records),"records":records,"canonicals":canonicals},ensure_ascii=False))
`
function actualStoreAccepts(records: Fact[]) {
  const child = spawnSync(
    resolve('.venv/bin/python'),
    ['-I', '-c', pythonCheck, resolve('packages/engine/src')],
    { input: JSON.stringify(records), encoding: 'utf8', timeout: 10000, maxBuffer: 1024 * 1024 },
  )
  expect(child.error, 'Actual isolated Python must start').toBeUndefined()
  expect(child.signal).toBeNull()
  expect(child.status, child.stderr).toBe(0)
  const result: unknown = JSON.parse(child.stdout)
  return result
}

afterEach(() => vi.restoreAllMocks())

describe('T02 new manual content IDs; unit plus actual Python pure-function validation only', () => {
  it('pins the first real UI tuple and checks all Python golden records with the actual Store', () => {
    expect(vector('first-real-ui-tuple').fact.id).toBe(firstId)
    expect(actualStoreAccepts(golden.cases.map((item) => item.fact))).toEqual({
      accepted: golden.cases.length,
      records: golden.cases.map((item) => item.fact),
      canonicals: golden.cases.map((item) => item.canonical),
    })
  })

  it.each(golden.cases)('matches the independent Store golden for $name', async (item) => {
    const read = source(),
      before = structuredClone(read)
    const fact = triple(item.fact),
      input = structuredClone(fact)
    // Await deliberately supports both the old synchronous implementation and
    // the intended asynchronous WebCrypto implementation, so old source runs red.
    expect(await newManualFactPlan(read, fact)).toEqual({ manual: [item.fact] })
    expect(fact).toEqual(input)
    expect(read).toEqual(before)
  })

  it('returns the same content-derived ID for repeated calls with the exact same tuple', async () => {
    const item = vector('first-real-ui-tuple')
    const left = await newManualFactPlan(source(), triple(item.fact))
    const right = await newManualFactPlan(source(), triple(item.fact))
    expect(left).toEqual({ manual: [item.fact] })
    expect(right).toEqual(left)
  })

  it('keeps plain/language/datatype lexical terms and NFC/NFD text distinct without normalizing', async () => {
    const names = ['plain-seven', 'language-seven', 'integer-seven', 'unicode-nfc', 'unicode-nfd']
    const ids: string[] = []
    for (const name of names) {
      const item = vector(name)
      const plan = await newManualFactPlan(source(), triple(item.fact))
      expect(plan).toEqual({ manual: [item.fact] })
      ids.push(plan.manual![0]!.id)
    }
    expect(new Set(ids).size).toBe(names.length)
    expect(vector('unicode-nfc').fact.object).not.toBe(vector('unicode-nfd').fact.object)
  })

  it('the actual Store._fact accepts every TS-produced record without replacing its ID', async () => {
    const records: Fact[] = []
    for (const item of golden.cases) {
      const plan = await newManualFactPlan(source(), triple(item.fact))
      expect(plan.manual).toHaveLength(1)
      records.push(plan.manual![0]!)
    }
    expect(actualStoreAccepts(records)).toEqual({
      accepted: golden.cases.length,
      records,
      canonicals: golden.cases.map((item) => item.canonical),
    })
  })

  it('captures the original tuple before awaiting a deferred WebCrypto digest', async () => {
    const item = vector('first-real-ui-tuple')
    const fact = triple(item.fact)
    const originalSource = source(),
      before = structuredClone(originalSource)
    const realDigest = crypto.subtle.digest.bind(crypto.subtle)
    let release!: (result: ArrayBuffer) => void
    const blocked = new Promise<ArrayBuffer>((resolveDigest) => {
      release = resolveDigest
    })
    const spy = vi.spyOn(crypto.subtle, 'digest').mockReturnValue(blocked)
    const pending = Promise.resolve(newManualFactPlan(originalSource, fact))
    fact.subject = 'urn:changed:subject'
    fact.predicate = 'urn:changed:predicate'
    fact.object = '"changed after invocation"'
    try {
      expect(spy).toHaveBeenCalledTimes(1)
      const [algorithm, input] = spy.mock.calls[0]!
      expect(typeof algorithm === 'string' ? algorithm : algorithm.name).toBe('SHA-256')
      const captured = ArrayBuffer.isView(input)
        ? new Uint8Array(input.buffer, input.byteOffset, input.byteLength)
        : new Uint8Array(input)
      expect(Array.from(captured)).toEqual(Array.from(new TextEncoder().encode(item.canonical)))
      release(await realDigest('SHA-256', captured.slice()))
      expect(await pending).toEqual({ manual: [item.fact] })
      expect(originalSource).toEqual(before)
    } finally {
      release(new ArrayBuffer(32))
      await pending.catch(() => undefined)
    }
  })

  for (const field of ['subject', 'predicate', 'object'] as const) {
    for (const [name, code] of [
      ['high', 0xd800],
      ['low', 0xdfff],
    ] as const) {
      it(`rejects an unpaired ${name} surrogate in ${field} before lossy UTF-8 hashing`, async () => {
        const fact = triple(vector('first-real-ui-tuple').fact)
        const scalar = String.fromCharCode(code)
        fact[field] = field === 'object' ? `"bad${scalar}"` : `urn:bad:${scalar}`
        const spy = vi.spyOn(crypto.subtle, 'digest')
        await expect(
          Promise.resolve().then(() => newManualFactPlan(source(), fact)),
        ).rejects.toThrow()
        expect(spy).not.toHaveBeenCalled()
      })
    }
  }
})
